const agents=[
['Minh','Trưởng phòng','Điều phối & chiến lược','🧭','#e4edcf','Nhận brief, xác định mục tiêu và phân công cho toàn đội.','Brief từ giám đốc','Bản phân công, mục tiêu và tiêu chí nghiệm thu','Chia chiến dịch thành nghiên cứu → chiến lược → sản xuất → kiểm duyệt. Giả định cần xác nhận: chân dung khách hàng, ngân sách, thời hạn.'],
['An','Research','Nghiên cứu thị trường','🔎','#e4eada','Tìm hiểu khách hàng, thị trường và đối thủ.','Brief và câu hỏi nghiên cứu','Bảng insight và giả thuyết cần xác minh','Đề xuất phỏng vấn 5 khách hàng và so sánh 3 đối thủ. Chưa có dữ liệu thực tế; mọi insight cần được kiểm chứng.'],
['Linh','Strategy','Kế hoạch chiến dịch','♟️','#e9e3d5','Chuyển nghiên cứu thành thông điệp, kênh và lộ trình.','Brief + nghiên cứu','Khung chiến dịch và chỉ số đánh giá','Tuần 1: giới thiệu vấn đề. Tuần 2: giải thích lợi ích. Tuần 3: bằng chứng. Tuần 4: lời mời trải nghiệm. KPI để giám đốc xác nhận.'],
['Mai','Content','Nội dung & kịch bản','✍️','#f0e2d8','Viết bài, tiêu đề và kịch bản theo chiến lược.','Thông điệp và chân dung khách hàng','Bản nháp nội dung','Khung bài: tình huống khách hàng → lợi ích sản phẩm → bằng chứng cần bổ sung → lời mời tìm hiểu. Gói bàn giao mẫu: 3 bài giới thiệu và 2 kịch bản ngắn.'],
['Huy','Creative','Thiết kế & hình ảnh','🎨','#e7dff0','Xây ý tưởng hình ảnh và hướng dẫn sản xuất.','Thông điệp + bản nháp nội dung','Creative brief','Hướng hình ảnh mẫu: tông tự nhiên, sản phẩm làm điểm nhấn, tiêu đề ngắn. Chuẩn bị bố cục vuông và dọc; dùng tài sản có quyền sử dụng.'],
['Nam','SEO','Tìm kiếm tự nhiên','🌱','#e1ebd1','Lập cụm chủ đề và cấu trúc bài cho tìm kiếm.','Sản phẩm + nhu cầu khách hàng','Kế hoạch chủ đề SEO','Ba cụm chủ đề: hướng dẫn chọn sản phẩm, câu hỏi thường gặp, cách sử dụng. Chưa tra cứu lượng tìm kiếm hoặc thứ hạng thực tế.'],
['Vy','Social','Mạng xã hội','💬','#dce9e7','Lập lịch nội dung và quy trình phản hồi.','Nội dung + creative brief','Lịch đăng nháp','Lịch mẫu: thứ Hai giáo dục, thứ Tư hậu trường, thứ Sáu giải đáp. Mọi bài đăng vẫn là nháp, cần người duyệt trước khi xuất bản.'],
['Khoa','Performance','Quảng cáo & thử nghiệm','🎯','#ede6cf','Đề xuất quảng cáo và thiết kế thử nghiệm.','Thông điệp + tài sản nội dung','Kế hoạch A/B','Thử hai thông điệp với cùng đối tượng và định dạng. Ngân sách chờ xác nhận; không tạo quảng cáo hoặc phát sinh chi phí trong demo.'],
['Thảo','CRM','Chăm sóc khách hàng','💌','#f0e0df','Thiết kế hành trình và nội dung chăm sóc.','Chân dung khách hàng + ưu đãi đã duyệt','Chuỗi chăm sóc nháp','Chuỗi mẫu: chào mừng → hướng dẫn sử dụng → giải đáp → hỏi trải nghiệm. Chỉ liên hệ người đồng ý nhận tin; demo không gửi tin nhắn.'],
['Đức','Analytics','Dữ liệu & đo lường','📊','#dde7ed','Thiết lập đo lường và khung báo cáo.','Mục tiêu + kế hoạch kênh','Bảng chỉ số đề xuất','Theo dõi lượt tiếp cận, tương tác, truy cập và chuyển đổi. Cần nối nguồn dữ liệu thật để đánh giá; chưa có kết quả hiệu quả chiến dịch.'],
['Quỳnh','Quality','Kiểm duyệt chất lượng','🛡️','#e6e8db','Kiểm tra tính nhất quán, tuyên bố và mức độ hoàn thiện.','Toàn bộ đầu ra của đội ngũ','Báo cáo duyệt và danh sách bổ sung','Đã hoàn tất mô phỏng bàn giao. Trước khi thực thi cần xác minh thông tin sản phẩm, quyền tài sản, KPI và ngân sách. Trình giám đốc duyệt bản kế hoạch.']];
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state={title:'',brief:'',step:0,approved:false},timer=null;try{const saved=JSON.parse(localStorage.getItem('marketing-office-demo-v1'));if(saved&&typeof saved.title==='string'&&typeof saved.brief==='string'&&Number.isInteger(saved.step)&&saved.step>=0&&saved.step<=11)state=saved}catch{};
function persist(){try{localStorage.setItem('marketing-office-demo-v1',JSON.stringify(state))}catch{}}
function status(i){return i<state.step?'Đã bàn giao':state.title&&i===state.step?'Đang xử lý mô phỏng':'Chờ brief'}
function render(){
$('#office').innerHTML=agents.map((a,i)=>`<button class="agent ${i===0?'leader':''} ${i<state.step?'done':state.title&&i===state.step?'working':''}" data-agent="${i}"><div class="avatar" style="--color:${a[4]}">${a[3]}</div><div><h3>${a[0]} · ${a[1]}</h3><p>${a[2]}</p><span class="status">${status(i)}</span></div></button>`).join('');
$('#campaignMetric').innerHTML=`${state.title?1:0} <span>${state.approved?'đã duyệt':'đang triển khai'}</span>`;$('#progressMetric').innerHTML=`${state.step} <span>/ 11 đầu việc</span>`;$('#briefTitle').textContent=state.title||'Chưa có chiến dịch';$('#briefText').textContent=state.brief||'Thử chiến dịch mẫu hoặc giao brief của bạn để xem các agent phối hợp.';$('#sample').classList.toggle('hidden',!!state.title);$('#step').disabled=!state.title||state.step>=11;$('#auto').disabled=!state.title||state.step>=11;$('#auto').textContent=timer?'Ⅱ Tạm dừng':'▶ Tự chạy';$('#approve').classList.toggle('hidden',state.step!==11||state.approved);
$('#logs').innerHTML=(!state.title?'<p class="muted">Đội ngũ sẵn sàng nhận brief đầu tiên.</p>':`<div class="log"><b>Giám đốc đã giao brief</b><span>${esc(state.title)}</span></div>`)+agents.slice(0,state.step).map(a=>`<div class="log"><b>${a[0]} · ${a[1]}</b><span>Đã bàn giao: ${a[7]}</span></div>`).join('')+(state.approved?'<div class="log"><b>Giám đốc đã duyệt demo</b><span>Hoàn tất chu trình mô phỏng. Chưa thực thi ra bên ngoài.</span></div>':'');
$('#tasks').innerHTML=agents.map((a,i)=>`<div class="task"><div><b>${String(i+1).padStart(2,'0')} · ${a[2]}</b><p class="muted">${a[0]} nhận ${i===0?'brief từ bạn':'bàn giao từ '+agents[i-1][1]} → ${i===10?'trình bạn duyệt':agents[i+1][1]}</p></div><span>${status(i)}</span></div>`).join('');
$('#results').innerHTML=state.step?agents.slice(0,state.step).map(a=>`<article class="result"><small>ĐẦU RA MÔ PHỎNG · ${esc(state.title)}</small><h3>${a[3]} ${a[7]}</h3><p>${a[8]}</p><small>${a[0]} · ${a[1]}</small></article>`).join(''):'<div class="empty">Chưa có kết quả bàn giao.<br>Giao brief và chạy mô phỏng để xem đầu ra từng agent.</div>';persist();}
function stop(){if(timer)clearInterval(timer);timer=null}function next(){if(!state.title||state.step>=11)return;state.step++;if(state.step===11)stop();render()}function start(title,brief){stop();state={title,brief,step:0,approved:false};render()}
$('#sample').onclick=()=>start('Ra mắt cà phê Mộc','Chiến dịch minh họa: giới thiệu cà phê rang mộc cho dân văn phòng 25–35 tuổi. Kênh thử: Facebook và TikTok. Mục tiêu: xây dựng kế hoạch ra mắt trong 4 tuần. Ngân sách chưa xác định.');$('#step').onclick=next;$('#auto').onclick=()=>{if(timer)stop();else timer=setInterval(next,1800);render()};$('#approve').onclick=()=>{state.approved=true;render()};$('#reset').onclick=()=>{stop();state={title:'',brief:'',step:0,approved:false};render()};$('#newBrief').onclick=()=>$('#briefDialog').showModal();$('#briefForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const title=f.get('title').trim(),brief=f.get('brief').trim();if(!title||!brief)return;start(title,brief);$('#briefDialog').close();e.target.reset()};document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#office').onclick=e=>{const b=e.target.closest('[data-agent]');if(!b)return;const a=agents[+b.dataset.agent];$('#agentDetail').innerHTML=`<div class="avatar" style="--color:${a[4]}">${a[3]}</div><div class="eyebrow">AI AGENT · MÔ PHỎNG</div><h2>${a[0]} · ${a[1]}</h2><p class="detail-text">${a[5]}</p><p class="detail-text"><b>Đầu vào</b><br>${a[6]}</p><p class="detail-text"><b>Đầu ra bàn giao</b><br>${a[7]}</p><p class="muted">${status(+b.dataset.agent)} · Agent này chưa kết nối mô hình AI.</p>`;$('#agentDialog').showModal()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));['office','tasks','results'].forEach(id=>$('#'+id).classList.toggle('hidden',id!==b.dataset.view));$('#viewTitle').textContent={office:'Sơ đồ văn phòng',tasks:'Bảng công việc & bàn giao',results:'Kho kết quả mô phỏng'}[b.dataset.view]});render();
